	"settingsIntegrations.title": "Intégrations",
	"settingsIntegrations.tagline": "Récupérez vos courses depuis les applis et montres que vous utilisez déjà — ou déposez un fichier d'export groupé si vous préférez ne pas connecter de compte.",
	"settingsIntegrations.loading": "Chargement des intégrations…",
	"settingsIntegrations.emptyTitle": "Aucune intégration connectée",
	"settingsIntegrations.emptyText": "Connectez un compte ci-dessous pour que vos courses arrivent automatiquement. Ou utilisez les cartes d'import groupé si vous préférez déposer un export ponctuel.",
	"settingsIntegrations.availableHeading": "Intégrations disponibles",
	"settingsIntegrations.infoAbout": "À propos de {name}",
	"settingsIntegrations.strandedNote": "Cette connexion est toujours liée à votre compte mais ne peut pas se synchroniser ici. Déconnectez-la si vous n'en avez plus besoin.",
	"settingsIntegrations.stravaInfo": "Strava est une appli populaire pour enregistrer et partager ses courses. En la connectant, vos activités Strava sont copiées : les 90 derniers jours d'abord, puis chaque nouvelle activité dès qu'elle apparaît. Vous vous connectez à Strava et vous autorisez l'accès ; vous pouvez vous déconnecter à tout moment.",
	"settingsIntegrations.parkrunInfo": "parkrun est un 5 km gratuit et chronométré, organisé chaque semaine dans des parcs partout dans le monde. La connexion indique que vous y participez ; pour récupérer vos résultats, saisissez le numéro d'athlète de votre code-barres parkrun (celui qui commence par A) dans Réglages, Compte, puis choisissez « Récupérer les résultats parkrun ».",
	"settingsIntegrations.garminInfo": "Garmin Connect est l'endroit où une montre Garmin stocke vos activités. Le lien automatique de compte n'existe pas encore — Garmin doit l'autoriser. En attendant, « Import groupé depuis un export Garmin », plus bas sur cette page, récupère les mêmes courses depuis un fichier, sans aucun lien de compte.",
	"settingsIntegrations.healthkitInfo": "Apple HealthKit est le magasin santé de l'iPhone, où atterrissent les séances de toutes les applis. Il ne fonctionne que sur l'appareil lui-même : un navigateur web n'a donc rien à quoi se connecter — la synchronisation se fait dans l'appli iPhone.",
	"settingsIntegrations.stravaBulkInfo": "Connecter Strava ne récupère que l'activité récente. Si vous utilisez Strava depuis des années, un export groupé récupère tout. Demandez votre archive à Strava (Réglages, Mon compte, Télécharger ou supprimer votre compte), attendez l'e-mail — cela peut prendre quelques heures — puis déposez le zip ici. Les courses que vous avez déjà sont ignorées.",
	"settingsIntegrations.garminBulkInfo": "Cela récupère votre historique Garmin depuis un fichier plutôt que par un lien de compte. Exportez une activité depuis Garmin Connect avec « Exporter l'original », ou demandez vos données complètes dans la gestion de compte Garmin et déposez le zip ici quand l'e-mail arrive. Les courses que vous avez déjà sont ignorées.",
	"settingsIntegrations.stravaDescription": "Synchronisez automatiquement les activités depuis votre compte Strava",
	"settingsIntegrations.parkrunDescription": "Importez tout votre historique parkrun",
	"settingsIntegrations.parkrunRegionNote": "parkrun n'est présent que dans certains pays et il se peut qu'aucun événement n'ait lieu près de chez vous — vous pouvez quand même vous connecter avec votre identifiant d'athlète parkrun.",
	"settingsIntegrations.garminDescription": "Import groupé de fichiers .fit (activité unique ou export complet des données du compte). L'OAuth en direct nécessite l'approbation du programme développeur Garmin.",
