	"prefs.heading": "Préférences",
	"prefs.tagline": "Vos préférences sont regroupées selon ce qu'elles modifient. Choisissez un groupe pour voir et modifier ses réglages. Les changements sont enregistrés automatiquement et vous suivent sur tous les appareils où vous êtes connecté.",
	"prefs.displayTagline": "L'apparence des chiffres, des cartes et de l'appli. La langue et le thème s'appliquent à ce navigateur ; le reste vous suit sur tous les appareils où vous êtes connecté.",
	"prefs.recordingTagline": "Ce qui se passe quand vous lancez un enregistrement sur votre téléphone ou votre montre. Les changements sont enregistrés automatiquement.",
