	"prefs.bodyTagline": "Des informations facultatives sur votre corps, utilisées pour vos objectifs nutritionnels et les résultats par âge et par sexe. Les enregistrer nécessite votre consentement.",
	"prefs.privacyTagline": "Qui voit vos sorties, comment les autres coureurs vous trouvent et ce qui quitte votre appareil. Les changements sont enregistrés automatiquement.",
