	"prefs.hrMedicationSetMaxHr": "Indiquez ci-dessus une fréquence cardiaque max mesurée, lors d'un effort intense ou d'un test, pour que vos zones vous correspondent.",
	"prefs.demographicsHeading": "Données démographiques et corporelles",
	"prefs.demographicsDesc": "Facultatif. Le sexe et la tranche d'âge alimentent les filtres des classements de segments (les mêmes catégories que Strava) ; la taille et le poids alimentent vos objectifs de calories et de macros nutritionnels. Laissez un champ vide pour ignorer cet usage.",
	"prefs.demographicsConsentNotice": "Ces champs sont des données personnelles liées à la santé au sens de l'art. 9 du RGPD. Nous ne les traitons qu'avec votre consentement explicite et uniquement pour alimenter les vues par sexe et par tranche d'âge des classements de segments ainsi que vos objectifs nutritionnels. Consultez notre",
	"prefs.privacyPolicyLink": "politique de confidentialité",
	"prefs.demographicsConsentNoticeTail": " pour connaître l'ensemble des finalités, la durée de conservation et vos droits de retrait.",
	"prefs.demographicsConsent": "Je consens à ce que Threkir conserve mon sexe, ma date de naissance, ma taille et mon poids pour le classement par catégories des segments et les objectifs nutritionnels décrits ci-dessus (art. 9, par. 2, point a du RGPD).",
