	"deleteAccount.documentTitle": "Supprimer votre compte — Threkir",
	"deleteAccount.metaDescription": "Comment supprimer votre compte Threkir et toutes les données associées, avec ou sans l'app installée.",
	"deleteAccount.h1": "Supprimer votre compte",
	"deleteAccount.lead": "Cette page explique comment supprimer définitivement votre compte Threkir et les données qui y sont associées. Vous n'avez pas besoin d'avoir l'app installée pour demander la suppression.",
	"deleteAccount.lastUpdated": "Dernière mise à jour : {date}",
	"deleteAccount.s1Heading": "1. Supprimer votre compte vous-même",
	"deleteAccount.s1Intro": "Vous supprimez votre compte vous-même, et la suppression prend effet immédiatement :",
	"deleteAccount.s1WebLabel": "Sur le web",
	"deleteAccount.s1WebPrefix": " : connectez-vous, ouvrez ",
	"deleteAccount.s1WebLink": "Paramètres → Compte",
	"deleteAccount.s1WebMiddle": " et choisissez ",
	"deleteAccount.s1WebAction": "Supprimer le compte",
	"deleteAccount.s1WebSuffix": ". Il vous sera demandé de saisir l'adresse e-mail de votre compte pour confirmer. (Si vous ouvrez ce lien sans être connecté, il vous fait passer par la connexion puis vous ramène ici.)",
	"deleteAccount.s1MobileLabel": "Dans l'app mobile",
	"deleteAccount.s1MobileBody": " : Paramètres → Compte → Supprimer le compte, avec la même confirmation par saisie.",
	"deleteAccount.s1PermanentPrefix": "La suppression est ",
	"deleteAccount.s1PermanentEmphasis": "définitive et irréversible",
	"deleteAccount.s1PermanentSuffix": ". Une fois terminée, nous envoyons un unique e-mail de confirmation à l'adresse du compte, en guise de reçu.",
	"deleteAccount.s2Heading": "2. Si vous ne pouvez pas vous connecter",
	"deleteAccount.s2Prefix": "Écrivez à ",
	"deleteAccount.s2Suffix": " depuis l'adresse e-mail du compte et demandez-nous de le supprimer. Nous vérifions la demande en contrôlant cette adresse (ou en vous faisant confirmer un lien qui lui est envoyé), puis nous effectuons la même suppression que celle décrite ci-dessous et vous confirmons qu'elle est faite — dans un délai d'un mois au plus, généralement bien plus tôt.",
	"deleteAccount.s3Heading": "3. Ce qui est supprimé",
	"deleteAccount.s3Intro": "La suppression du compte efface vos données de notre base de données et de notre stockage de fichiers, notamment :",
	"deleteAccount.s3Profile": "votre profil (nom, avatar, paramètres, relations d'abonnement) ;",
	"deleteAccount.s3Runs": "les courses et leurs traces GPS, les itinéraires, les résultats de compétition et les records personnels ;",
	"deleteAccount.s3Files": "les photos et tous les autres fichiers que vous avez envoyés, y compris les exports de données générés ;",
	"deleteAccount.s3Gym": "les séances de musculation, les routines, les plans de séance, les journaux alimentaires et les mesures corporelles ;",
	"deleteAccount.s3Training": "les plans d'entraînement, l'historique des conversations avec le coach et les consentements au Coach IA ;",
	"deleteAccount.s3Social": "les publications, les commentaires, les kudos, les messages privés et les adhésions aux clubs ;",
	"deleteAccount.s3Notifications": "les notifications et les jetons de notifications push ;",
	"deleteAccount.s3ThirdParty": "les ressources tierces associées : une autorisation Strava connectée est révoquée, un enregistrement d'abonné RevenueCat est supprimé, et un compte de paiement Stripe connecté est dissocié et clôturé (Stripe conserve les enregistrements de transactions en vertu de ses propres obligations légales).",
	"deleteAccount.s4Heading": "4. Ce qui est conservé, et combien de temps",
	"deleteAccount.s4BackupsLabel": "Sauvegardes chiffrées",
	"deleteAccount.s4BackupsPrefix": " : un compte supprimé peut subsister dans les sauvegardes de restauration à un instant donné pendant ",
	"deleteAccount.s4BackupsWindow": "28 jours",
	"deleteAccount.s4BackupsSuffix": " au plus, avant leur expiration. Les sauvegardes ne servent jamais à restaurer un compte supprimé.",
	"deleteAccount.s4AuditLabel": "Un journal de suppression minimal",
	"deleteAccount.s4AuditBody": " : un identifiant haché de façon irréversible et le décompte des éléments supprimés, conservés pour pouvoir prouver que la suppression a eu lieu. Il ne permet ni de vous identifier ni de récupérer la moindre donnée.",
	"deleteAccount.s4PaymentsLabel": "Enregistrements des transactions de paiement",
	"deleteAccount.s4PaymentsBody": " : conservés par les prestataires de paiement (Stripe, les boutiques d'applications) en vertu de leurs propres obligations légales ; nous ne détenons nous-mêmes aucune donnée de carte.",
	"deleteAccount.s4PolicyPrefix": "Le calendrier complet de conservation de chaque catégorie de données figure dans la ",
	"deleteAccount.s4PolicySuffix": ".",
	"deleteAccount.s5Heading": "5. Supprimer certaines données sans fermer le compte",
	"deleteAccount.s5Intro": "Pour supprimer des données précises sans supprimer le compte :",
	"deleteAccount.s5ItemsLabel": "Courses, itinéraires, photos, séances de musculation, entrées du journal alimentaire, publications, commentaires",
	"deleteAccount.s5ItemsBody": " : ouvrez l'élément et utilisez sa commande Supprimer. Les courses peuvent aussi être supprimées en lot depuis la liste des courses grâce à la sélection multiple.",
	"deleteAccount.s5ServicesLabel": "Services connectés",
	"deleteAccount.s5ServicesBody": " (Strava, parkrun et autres) : déconnectez-les dans Paramètres → Intégrations ; la déconnexion révoque notre accès.",
	"deleteAccount.s5OtherLabel": "Tout le reste, ou si vous préférez ne pas le faire dans l'app",
	"deleteAccount.s5OtherPrefix": " : écrivez à ",
	"deleteAccount.s5OtherSuffix": " en décrivant les données à supprimer, et nous nous en chargerons avec la même vérification et le même délai qu'à la section 2.",
	"deleteAccount.s5BackupsPrefix": "Les éléments supprimés quittent les sauvegardes chiffrées dans la même fenêtre de 28 jours décrite ci-dessus. Vous pouvez aussi ",
	"deleteAccount.s5ExportLink": "exporter vos données",
	"deleteAccount.s5BackupsSuffix": " avant de supprimer quoi que ce soit.",
	"deleteAccount.s6Heading": "6. Documents associés",
